using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class WeaponAudioCheck {
static BokumyakuGame g;static int index,frame,maxVoices;static double start;static List<object> results;static BokumyakuGame.AudioPreferences old;static string[] names={"point","pierce","bleed","sweep","enso","resonance"};
public static object Run(){g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated Play required");old=g.AudioSettings;g.SetAudioSettings(.6f,.4f,.5f,false);if(g.LoadedAudioCount!=8||g.LoadedWeaponAudioCount!=6)throw new Exception("Missing clips");results=new List<object>();index=maxVoices=0;Application.runInBackground=true;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();Begin();EditorApplication.update+=Poll;return "Six live weapon checks started; 20 seconds maximum per weapon";}
static void Begin(){g.AbandonRun();foreach(var s in g.GetComponents<AudioSource>())if(!s.loop)s.Stop();g.SetWeapon((WeaponKind)index);g.SetBuild(BuildPreset.Manual);g.SetSpeed(2);g.TryStartRun(42);g.SetAutoRepeat(false);g.SetPaused(false);start=EditorApplication.timeSinceStartup;frame=Time.frameCount;}
static void Poll(){if(g==null||!EditorApplication.isPlaying){EditorApplication.update-=Poll;return;}EditorApplication.QueuePlayerLoopUpdate();if(frame==Time.frameCount)return;frame=Time.frameCount;try{maxVoices=Math.Max(maxVoices,g.ActiveCombatVoices);string expected="sfx_attack_"+names[index];var s=g.GetComponents<AudioSource>().FirstOrDefault(x=>x.isPlaying&&x.clip!=null&&x.clip.name==expected&&x.volume>0&&!x.mute);if(s!=null){if(Math.Abs(s.volume-.135f)>.001f)throw new Exception("Attack gain mismatch");if(s.clip.frequency!=48000||s.clip.channels!=1)throw new Exception("Clip format mismatch");results.Add(new{weapon=((WeaponKind)index).ToString(),clip=s.clip.name,tick=g.Run.TickCount,volume=s.volume,frequency=s.clip.frequency,channels=s.clip.channels,seconds=s.clip.length});index++;if(index==6){Finish(null);return;}Begin();}else if(EditorApplication.timeSinceStartup-start>20)Finish("Timeout: "+expected);}catch(Exception e){Finish(e.ToString());}}
static void Finish(string error){EditorApplication.update-=Poll;g.SetPaused(true);g.SetAudioSettings(.6f,.4f,.5f,true);bool muted=g.GetComponents<AudioSource>().All(s=>s.mute||s.volume==0);g.ReloadAudioSettings();bool persisted=g.AudioSettings.Muted;g.SetAudioSettings(old.Master,old.Music,old.Effects,old.Muted);File.WriteAllText(Path.GetFullPath("../docs/evidence/weapon-audio-routing.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=error==null&&results.Count==6&&muted&&persisted&&maxVoices<=4,error,results,maxVoices,muted,persisted,method="Six actual seed42 Manual 2x runs; observe live audible AudioSources after simulation attacks. Isolated saves. Not subjective listening or device output verification."},Newtonsoft.Json.Formatting.Indented));}
}
